insert into public.artists (id, name, image_url, description, popularity) values
  ('10000000-0000-0000-0000-000000000001','YOASOBI','https://picsum.photos/seed/yoasobi/600','소설을 음악으로 만드는 프로젝트. "夜に駆ける", "アイドル"으로 세계적인 인기를 얻었다.', 98),
  ('10000000-0000-0000-0000-000000000002','Fujii Kaze','https://picsum.photos/seed/fujiikaze/600','오카야마 출신 싱어송라이터. 소울/펑크 기반의 독보적인 그루브가 특징이다.', 95),
  ('10000000-0000-0000-0000-000000000003','Kenshi Yonezu','https://picsum.photos/seed/yonezu/600','작곡가 겸 싱어송라이터. "Lemon", "KICK BACK" 등 히트곡을 다수 보유.', 97),
  ('10000000-0000-0000-0000-000000000004','Aimyon','https://picsum.photos/seed/aimyon/600','솔직한 가사와 어쿠스틱 사운드로 사랑받는 싱어송라이터.', 90),
  ('10000000-0000-0000-0000-000000000005','Official HIGE DANdism','https://picsum.photos/seed/higedan/600','밴드 사운드와 클래식한 팝 멜로디를 결합한 4인조 밴드.', 93),
  ('10000000-0000-0000-0000-000000000006','King Gnu','https://picsum.photos/seed/kinggnu/600','장르를 넘나드는 실험적 사운드로 유명한 4인조 밴드.', 92),
  ('10000000-0000-0000-0000-000000000007','Ado','https://picsum.photos/seed/ado/600','강렬한 보컬 표현력으로 주목받는 얼굴 없는 가수.', 94),
  ('10000000-0000-0000-0000-000000000008','LiSA','https://picsum.photos/seed/lisa/600','파워풀한 록 보컬로 애니메이션 주제가에서 강세를 보이는 아티스트.', 91),
  ('10000000-0000-0000-0000-000000000009','Vaundy','https://picsum.photos/seed/vaundy/600','장르 융합적인 프로듀싱과 보컬을 동시에 소화하는 신세대 아티스트.', 88),
  ('10000000-0000-0000-0000-000000000010','Mrs. GREEN APPLE','https://picsum.photos/seed/mrsgreenapple/600','드라마틱한 편곡과 대중적인 멜로디가 특징인 밴드.', 89),
  ('10000000-0000-0000-0000-000000000011','back number','https://picsum.photos/seed/backnumber/600','섬세한 발라드로 사랑받는 3인조 밴드.', 85),
  ('10000000-0000-0000-0000-000000000012','Yorushika','https://picsum.photos/seed/yorushika/600','문학적인 가사와 몽환적인 사운드가 매력적인 록 유닛.', 87)
