insert into public.posts (id, user_id, category, title, content, music_id, view_count, created_at) values
  ('40000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000001','recommendation','요즘 밤에 듣기 좋은 J-POP 추천해주세요.','조용한 밤에 산책하면서 들을만한 잔잔한 J-POP 찾고 있어요. 감성적인 곡 위주로 추천 부탁드려요!',null,132,now() - interval '2 days'),
  ('40000000-0000-0000-0000-000000000002','00000000-0000-0000-0000-000000000002','recommendation','Fujii Kaze의 Shinunoga E-Wa 추천합니다','밤에 들으면 분위기가 정말 좋아요. 그루브가 살아있는 곡이라 드라이브할 때도 잘 어울립니다.','30000000-0000-0000-0000-000000000005',210,now() - interval '2 days'),
  ('40000000-0000-0000-0000-000000000003','00000000-0000-0000-0000-000000000003','question','J-POP 입문하려는데 어떤 아티스트부터 들어보면 좋을까요?','최근에 애니 주제가로 J-POP에 관심이 생겼는데 어디서부터 시작해야 할지 모르겠어요.',null,341,now() - interval '5 days'),
  ('40000000-0000-0000-0000-000000000004','00000000-0000-0000-0000-000000000004','artist','YOASOBI부터 들어보는 걸 추천해요','소설을 원작으로 한 곡들이라 스토리텔링이 확실해요. 夜に駆ける부터 들어보세요!','30000000-0000-0000-0000-000000000001',298,now() - interval '5 days'),
  ('40000000-0000-0000-0000-000000000005','00000000-0000-0000-0000-000000000005','question','Kenshi Yonezu 노래 중에 처음 듣기 좋은 곡은?','Lemon 말고 다른 곡도 궁금해요. 앨범 전체를 관통하는 분위기가 궁금합니다.','30000000-0000-0000-0000-000000000009',176,now() - interval '4 days'),
  ('40000000-0000-0000-0000-000000000006','00000000-0000-0000-0000-000000000006','album','STRAY SHEEP 앨범 통째로 들어보세요','Lemon, パプリカ, KICK BACK까지 다 들어있는 명반입니다. 처음부터 끝까지 버릴 곡이 없어요.','30000000-0000-0000-0000-000000000009',201,now() - interval '6 days'),
  ('40000000-0000-0000-0000-000000000007','00000000-0000-0000-0000-000000000007','playlist','드라이브할 때 듣는 J-POP 플레이리스트 공유해요','King Gnu, Vaundy 위주로 신나는 곡들만 모아봤어요. 다들 드라이브곡 추천 있으면 댓글 부탁드려요.',null,156,now() - interval '3 days'),
  ('40000000-0000-0000-0000-000000000008','00000000-0000-0000-0000-000000000008','free','J-POP 듣기 시작한 지 1년, 최애 다섯 곡 정리','1년 동안 들으면서 진짜 좋았던 곡들 모아봤어요. 다들 최애곡 뭔가요?',null,289,now() - interval '7 days'),
  ('40000000-0000-0000-0000-000000000009','00000000-0000-0000-0000-000000000009','recommendation','우울할 때 힘이 되는 J-POP 있을까요','요즘 힘든 일이 있어서 위로가 되는 곡을 찾고 있어요.',null,98,now() - interval '1 days'),
  ('40000000-0000-0000-0000-000000000010','00000000-0000-0000-0000-000000000010','recommendation','Ado의 うっせぇわ 강력 추천','에너지 넘치는 곡이라 스트레스 풀릴 때 딱이에요.','30000000-0000-0000-0000-000000000021',245,now() - interval '8 days'),
  ('40000000-0000-0000-0000-000000000011','00000000-0000-0000-0000-000000000001','question','LiSA 곡 중에 애니 안 본 사람도 좋아할 곡 있나요?','紅蓮華 말고 다른 곡도 추천 받고 싶어요.','30000000-0000-0000-0000-000000000023',112,now() - interval '9 days'),
  ('40000000-0000-0000-0000-000000000012','00000000-0000-0000-0000-000000000002','artist','Official HIGE DANdism 밴드 사운드가 좋은 이유','Pretender 편곡이 정말 섬세해요. 밴드 각 파트가 다 살아있는 느낌.','30000000-0000-0000-0000-000000000015',167,now() - interval '10 days'),
  ('40000000-0000-0000-0000-000000000013','00000000-0000-0000-0000-000000000003','free','J-POP 가사 번역하면서 느낀 점','가사를 직접 번역해보니 곡에 대한 애정이 더 커지더라고요. 다들 가사 찾아보시나요?',null,88,now() - interval '11 days'),
  ('40000000-0000-0000-0000-000000000014','00000000-0000-0000-0000-000000000004','playlist','내 최애곡 모음 플레이리스트','제가 가장 좋아하는 곡들만 모았어요. 취향 비슷하신 분 있으면 댓글 남겨주세요.',null,143,now() - interval '12 days'),
  ('40000000-0000-0000-0000-000000000015','00000000-0000-0000-0000-000000000005','album','Yorushika 幻燈 앨범 분위기가 독특해요','문학적인 가사랑 몽환적인 사운드 조합이 진짜 좋아요.','30000000-0000-0000-0000-000000000032',77,now() - interval '13 days'),
  ('40000000-0000-0000-0000-000000000016','00000000-0000-0000-0000-000000000006','question','J-POP 라이브 영상 추천 받아요','스튜디오 버전 말고 라이브 버전이 더 좋은 곡들 있으면 알려주세요.',null,64,now() - interval '14 days')
insert into public.answers (id, post_id, user_id, content, created_at) values
  ('50000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000002','Fujii Kaze의 Shinunoga E-Wa 추천합니다. 밤에 들으면 분위기가 정말 좋아요.', now() - interval '2 days' + interval '1 hour'),
  ('50000000-0000-0000-0000-000000000002','40000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000005','Yorushika의 花に亡霊도 밤 분위기랑 잘 어울려요.', now() - interval '2 days' + interval '2 hour'),
  ('50000000-0000-0000-0000-000000000003','40000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000007','back number 발라드도 강추합니다.', now() - interval '1 days' + interval '3 hour'),
  ('50000000-0000-0000-0000-000000000004','40000000-0000-0000-0000-000000000003','00000000-0000-0000-0000-000000000004','YOASOBI부터 들어보는 걸 추천해요.', now() - interval '5 days' + interval '1 hour'),
  ('50000000-0000-0000-0000-000000000005','40000000-0000-0000-0000-000000000003','00000000-0000-0000-0000-000000000006','Kenshi Yonezu도 입문으로 좋아요. Lemon 들어보세요.', now() - interval '4 days' + interval '2 hour'),
  ('50000000-0000-0000-0000-000000000006','40000000-0000-0000-0000-000000000003','00000000-0000-0000-0000-000000000008','Official HIGE DANdism은 밴드 사운드 좋아하면 딱이에요.', now() - interval '4 days' + interval '5 hour'),
  ('50000000-0000-0000-0000-000000000007','40000000-0000-0000-0000-000000000003','00000000-0000-0000-0000-000000000009','저는 Ado로 입문했는데 강렬해서 좋았어요.', now() - interval '3 days' + interval '1 hour'),
  ('50000000-0000-0000-0000-000000000008','40000000-0000-0000-0000-000000000005','00000000-0000-0000-0000-000000000001','パプリカ도 정말 좋아요, 밝은 느낌이라 입문곡으로도 좋습니다.', now() - interval '4 days' + interval '3 hour'),
  ('50000000-0000-0000-0000-000000000009','40000000-0000-0000-0000-000000000005','00000000-0000-0000-0000-000000000003','KICK BACK 편곡이 진짜 독특해요, 꼭 들어보세요.', now() - interval '3 days' + interval '7 hour'),
  ('50000000-0000-0000-0000-000000000010','40000000-0000-0000-0000-000000000007','00000000-0000-0000-0000-000000000002','저는 드라이브할 때 Vaundy 踊り子 자주 들어요.', now() - interval '3 days' + interval '2 hour'),
  ('50000000-0000-0000-0000-000000000011','40000000-0000-0000-0000-000000000007','00000000-0000-0000-0000-000000000010','King Gnu 白日 넣으면 분위기 확 살아나요.', now() - interval '2 days' + interval '4 hour'),
  ('50000000-0000-0000-0000-000000000012','40000000-0000-0000-0000-000000000008','00000000-0000-0000-0000-000000000004','저도 비슷한 시기에 시작했는데 취향이 겹치네요!', now() - interval '6 days' + interval '2 hour'),
  ('50000000-0000-0000-0000-000000000013','40000000-0000-0000-0000-000000000008','00000000-0000-0000-0000-000000000005','마리ーゴールド는 진짜 명곡이죠.', now() - interval '6 days' + interval '5 hour'),
  ('50000000-0000-0000-0000-000000000014','40000000-0000-0000-0000-000000000009','00000000-0000-0000-0000-000000000006','Pretender 들어보세요. 위로가 많이 됐어요.', now() - interval '1 days' + interval '2 hour'),
  ('50000000-0000-0000-0000-000000000015','40000000-0000-0000-0000-000000000009','00000000-0000-0000-0000-000000000007','Subtitle도 잔잔하게 위로되는 곡이에요.', now() - interval '1 days' + interval '4 hour'),
  ('50000000-0000-0000-0000-000000000016','40000000-0000-0000-0000-000000000010','00000000-0000-0000-0000-000000000008','완전 공감이요, 스트레스 풀기 최고인 곡.', now() - interval '7 days' + interval '2 hour'),
  ('50000000-0000-0000-0000-000000000017','40000000-0000-0000-0000-000000000011','00000000-0000-0000-0000-000000000009','炎도 정말 좋아요, 발라드 느낌이라 입문용으로도 좋습니다.', now() - interval '8 days' + interval '3 hour'),
  ('50000000-0000-0000-0000-000000000018','40000000-0000-0000-0000-000000000012','00000000-0000-0000-0000-000000000010','Subtitle 라이브 버전도 꼭 찾아보세요.', now() - interval '9 days' + interval '2 hour'),
  ('50000000-0000-0000-0000-000000000019','40000000-0000-0000-0000-000000000013','00000000-0000-0000-0000-000000000001','저도 가사 찾아보는 편이에요, 훨씬 몰입돼요.', now() - interval '10 days' + interval '2 hour'),
  ('50000000-0000-0000-0000-000000000020','40000000-0000-0000-0000-000000000014','00000000-0000-0000-0000-000000000002','플레이리스트 취향 저격이네요!', now() - interval '11 days' + interval '2 hour'),
  ('50000000-0000-0000-0000-000000000021','40000000-0000-0000-0000-000000000015','00000000-0000-0000-0000-000000000003','幻燈 앨범 진짜 명반이죠, 저도 자주 들어요.', now() - interval '12 days' + interval '3 hour'),
  ('50000000-0000-0000-0000-000000000022','40000000-0000-0000-0000-000000000016','00000000-0000-0000-0000-000000000004','King Gnu 라이브는 밴드 실력이 확 느껴져서 좋아요.', now() - interval '13 days' + interval '2 hour')
